package com.bombay.restaurantintelligence.review;
import com.bombay.restaurantintelligence.analytics.DailyMetricService; import com.bombay.restaurantintelligence.domain.*; import com.bombay.restaurantintelligence.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ReviewServiceTest {@Mock ReviewItemRepository reviews;@Mock CategoryRepository categories;@Mock VendorRepository vendors;@Mock TransactionRepository transactions;@Mock AuditLogRepository audits;@Mock NormalizationMappingRepository mappings;@Mock DailyMetricService dailyMetrics;ReviewService service;@BeforeEach void setUp(){service=new ReviewService(reviews,categories,vendors,transactions,audits,mappings,dailyMetrics);}@Test void approvedReviewBecomesVerifiedAndIsAudited(){UUID id=UUID.randomUUID();TransactionEntity tx=transaction(TransactionStatus.REVIEW_REQUIRED);ReviewItem item=new ReviewItem(tx,"Unknown category","sabji");Category veg=new Category("VEGETABLES","Vegetables","PURCHASES");when(reviews.findById(id)).thenReturn(Optional.of(item));when(categories.findByCodeIgnoreCase("VEGETABLES")).thenReturn(Optional.of(veg));when(mappings.findFirstByRawTermIgnoreCaseAndCanonicalType("sabji","CATEGORY")).thenReturn(Optional.empty());when(mappings.save(any())).thenAnswer(i->i.getArgument(0));var result=service.approve(id,new ReviewService.CorrectionRequest("VEGETABLES",null,new BigDecimal("6500"),LocalDate.of(2026,9,25),"sabji","Owner confirmed"),"owner");assertThat(result.status()).isEqualTo("VERIFIED");assertThat(result.category()).isEqualTo("VEGETABLES");assertThat(tx.getStatus()).isEqualTo(TransactionStatus.VERIFIED);verify(transactions).save(tx);verify(audits).save(any(AuditLog.class));verify(mappings).save(any(NormalizationMapping.class));verify(dailyMetrics).refresh(LocalDate.of(2026,9,25));}@Test void rejectedReviewNeverBecomesVerified(){UUID id=UUID.randomUUID();TransactionEntity tx=transaction(TransactionStatus.REVIEW_REQUIRED);ReviewItem item=new ReviewItem(tx,"Low confidence","candidate");when(reviews.findById(id)).thenReturn(Optional.of(item));service.reject(id,"Not a business transaction","owner");assertThat(tx.getStatus()).isEqualTo(TransactionStatus.REJECTED);verify(transactions).save(tx);verify(audits).save(any(AuditLog.class));verify(dailyMetrics).refresh(LocalDate.of(2026,9,25));}private static TransactionEntity transaction(TransactionStatus status){TransactionEntity tx=new TransactionEntity();tx.setBusinessDate(LocalDate.of(2026,9,25));tx.setTransactionType(TransactionType.EXPENSE);tx.setAmount(new BigDecimal("500"));tx.setSourceType("IMAGE");tx.setStatus(status);return tx;}}
